'use strict';
// Authored artwork remains separated, editable, deterministic and on the shared race rig.
window.RUN=async()=>{const {ok,exc,out}=Kit.report(),t=T,A=t.PortraitArtwork,E=t.PortraitEngine,data=c=>c.getContext('2d').getImageData(0,0,c.width,c.height).data,signature=c=>c.toDataURL();
 try{
  await A.ready;ok(A.loaded&&A.partCount===50,'all fifty bundled painted masters decode without remote image requests');
  ok(t.PAINTED_PORTRAIT_ASSETS.length===2&&t.PAINTED_PORTRAIT_ASSETS.every(a=>a.src.startsWith('data:image/png;base64,')&&a.frames.length===25&&a.frames.every(([x,y,w,h])=>w>0&&h>0&&x>=0&&y>=0&&x+w<=a.width&&y+h<=a.height)),'both local art atlases expose twenty-five nonempty in-bounds frames');
  const config={...E.startProfile('male'),race:'human',face:'strong-jaw',hair:'waves',eyes:'keen',nose:'broad',beard:'none',headwear:'none',age:'young',marks:'none',clothing:'steel-cuirass'},base=A.build(config),before=Object.fromEntries(E.order.map(s=>[s.id,signature(base.layers[s.id])])),same=A.build(config);
  ok(E.order.length===19&&E.order.every(s=>base.layers[s.id]?.width===256&&base.layers[s.id].height===256),'all nineteen dynamic parts are independently exported on matching 256px canvases');
  ok(JSON.stringify(base.config)===JSON.stringify(E.normalize(config))&&JSON.stringify(base.anchors)===JSON.stringify(E.geometry(config))&&base.coordinateScale===2,'painted art retains the existing normalized recipe, rig and coordinate mapping');
  ok(E.order.every(s=>before[s.id]===signature(same.layers[s.id])),'the same recipe and palette reproduce every painted part exactly');
  for(const race of E.races)for(const key of ['eyes','mouth']){const variants=E.partsFor(race,key),signatures=new Set();for(const value of variants){const q=E.normalize({...E.startRace(race),[key]:value,beard:'none',headwear:'none',age:'young',marks:'none'}),p=A.build(q);signatures.add((key==='eyes'?['eyes','iris','eyelids']:['mouth','teeth']).map(id=>signature(p.layers[id])).join('|'));if(key==='eyes'){const d=data(p.layers.iris);for(const eye of p.anchors.eyes){let pupil=0;for(let y=Math.floor(eye.y*2)-6;y<=Math.floor(eye.y*2)+6;y++)for(let x=Math.floor(eye.x*2)-6;x<=Math.floor(eye.x*2)+6;x++){const k=(y*256+x)*4;if(d[k+3]&&Math.max(d[k],d[k+1],d[k+2])<90)pupil++;}if(!pupil)throw Error('Painted pupil lost: '+race+'/'+value);}}}ok(signatures.size===variants.length,race+' retains distinct painted artwork for every '+key+' option');}
  for(const [key,value,allowed] of [['hair','long',['hairFront','hairBack']],['nose','slender',['nose']],['eyes','heavy',['eyes','iris','eyelids']],['clothing','mail',['clothing','armor','torso']]]){const p=A.build({...config,[key]:value});ok(E.order.filter(s=>!allowed.includes(s.id)).every(s=>before[s.id]===signature(p.layers[s.id])),key+' swaps its painted parts without changing unrelated artwork');ok(allowed.some(id=>before[id]!==signature(p.layers[id])),key+' selection visibly changes artwork');}
  for(const [channel,color,allowed] of [['skin','#7c563e',['face','ears','nose','eyelids','torso','age','marks']],['hair','#b49d70',['hairFront','hairBack','brows','beard']],['iris','#8c4c32',['iris']]]){const p=A.build(config,{colors:{[channel]:color}});ok(E.order.filter(s=>!allowed.includes(s.id)).every(s=>before[s.id]===signature(p.layers[s.id])),channel+' tint preserves unrelated painted layers');ok(allowed.some(id=>before[id]!==signature(p.layers[id])),channel+' tint changes its own painted artwork');}
  const composite=A.composite(base),hidden=A.composite(base,{visible:{hairFront:false,hairBack:false}});ok(composite.width===256&&signature(composite)!==signature(hidden),'layer visibility changes composition without flattening the source parts');ok(E.order.every(s=>before[s.id]===signature(base.layers[s.id])),'compositing and layer toggles never mutate the exported artwork');
  let cases=0;for(const race of E.races)for(const profile of ['male','female'])for(const headwear of ['none','kettle','closed-knight-helm']){const q=E.normalize({...E.startRace(race,E.startProfile(profile)),profile,headwear,age:'young',marks:'none'}),p=A.build(q),im=A.composite(p),rgba=data(im);if(!rgba.some((v,i)=>i%4===3&&v))throw Error('Blank '+race+'/'+profile+'/'+headwear);if(rgba[3]||rgba[(256*256-1)*4+3])throw Error('Opaque portrait backdrop');if(JSON.stringify(p.anchors)!==JSON.stringify(E.geometry(q)))throw Error('Race proportions changed');for(const id of ['face','clothing','armor','headwearFront']){const src=data(p.template.layers[id]),paint=data(p.layers[id]);for(let y=0;y<128;y++)for(let x=0;x<128;x++)if(paint[((y*2)*256+x*2)*4+3]!==src[(y*128+x)*4+3])throw Error('Part fit changed: '+race+'/'+headwear+'/'+id);}cases++;}
  ok(cases===24,'all races and profiles keep their transparent backgrounds, head proportions and fitted skin/armor/helmet masks');
  const dwarf=A.build({...E.startRace('dwarf'),beard:'dwarf-twin-braids',clothing:'dwarf-runic-plate',headwear:'dwarf-horned-helm'}),orc=A.build({...E.startRace('orc'),hair:'war-crest',mouth:'heavy-tusks',clothing:'orc-bare-cross-harness'});ok(data(dwarf.layers.beard).some((v,i)=>i%4===3&&v)&&data(orc.layers.teeth).some((v,i)=>i%4===3&&v),'braided dwarf beards and separate orc tusks retain visible painted-part coverage');
  const legacy=E.composite(E.build(config),{colors:E.colors});ok(signature(legacy)!==signature(A.render(config)),'the new appearance uses painted artwork rather than the previous procedural composite');
  const rec={config:E.normalize(config),colors:{...E.colors}},url=t.Faces.url(rec,true),im=new Image();im.src=url;await im.decode();ok(url.startsWith('data:image/png')&&im.width===t.FACES.px,'game portrait URLs render the new bundled parts at their normal UI size');
 }catch(e){exc(e)}finally{out()}
};
